private static int getHash(String string) {
    final int p = 16777619;
    int hash = (int)2166136261L;
    for(int i = 0; i < string.length(); i++) {
        hash = (hash ^ string.charAt(i)) * p;
    }
    hash += hash << 13;
    hash ^= hash >> 7;
    hash += hash << 3;
    hash ^= hash >> 17;
    hash += hash << 5;
    if(hash < 0) {
        hash = Math.abs(hash);
    }
    return hash;
}

