    int hash = getHash(ip);
    SortedMap<Integer, String> subMap = virtualNodes.tailMap(hash);
    Integer node = 0;
    if(!subMap.isEmpty()) {
        node = subMap.firstKey();
    }
    String virtualNode = subMap.get(node);
    return virtualNode.substring(0, virtualNode.indexOf("##"));
}

