import java.lang.reflect.*;
import java.util.*;

public class HashTest {
    static Method getHash, getServer, addVirtualNode, deleteServer, generateIp;
    @SuppressWarnings("unchecked")
    static TreeMap<Integer, String> virtualNodes;
    @SuppressWarnings("unchecked")
    static LinkedList<String> realNodes;

    // Independent FNV1_32 reference (same algorithm as the spec comment says)
    static int refHash(String s) {
        int hash = (int)2166136261L;
        for (int i = 0; i < s.length(); i++) hash = (hash ^ s.charAt(i)) * 16777619;
        hash += hash << 13;
        hash ^= hash >> 7;
        hash += hash << 3;
        hash ^= hash >> 17;
        hash += hash << 5;
        return hash < 0 ? Math.abs(hash) : hash;
    }

    public static void main(String[] args) throws Exception {
        Class<?> c = Class.forName("Main");
        getHash = c.getDeclaredMethod("getHash", String.class);
        getServer = c.getDeclaredMethod("getServer", String.class);
        addVirtualNode = c.getDeclaredMethod("addVirtualNode", String.class);
        deleteServer = c.getDeclaredMethod("deleteServer", String.class);
        generateIp = c.getDeclaredMethod("generateIp");
        for (Method m : new Method[]{getHash, getServer, addVirtualNode, deleteServer, generateIp}) m.setAccessible(true);
        Field vf = c.getDeclaredField("virtualNodes"); vf.setAccessible(true);
        Field rf = c.getDeclaredField("realNodes"); rf.setAccessible(true);
        virtualNodes = (TreeMap<Integer, String>) vf.get(null);
        realNodes = (LinkedList<String>) rf.get(null);

        // 1. getHash matches reference, and is non-negative
        for (String s : new String[]{"192.168.1.100", "a", "", "10.0.0.1##VN3", "服务器"}) {
            int got = (int) getHash.invoke(null, s);
            int exp = refHash(s);
            if (got != exp || got < 0) throw new AssertionError("getHash mismatch for '" + s + "': " + got + " != " + exp);
        }
        System.out.println("getHash OK (e.g. 192.168.1.100 -> " + getHash.invoke(null, "192.168.1.100") + ")");

        // 2. generateIp produces a.b.c.d with 1..255 octets
        for (int i = 0; i < 1000; i++) {
            String ip = (String) generateIp.invoke(null);
            String[] parts = ip.split("\\.");
            if (parts.length != 4) throw new AssertionError("bad ip: " + ip);
            for (String p : parts) {
                int v = Integer.parseInt(p);
                if (v < 1 || v > 255) throw new AssertionError("octet out of range: " + ip);
            }
        }
        System.out.println("generateIp OK (sample: " + generateIp.invoke(null) + ")");

        // 3. addVirtualNode adds exactly 10 vnodes per server
        realNodes.add("10.0.0.1");
        addVirtualNode.invoke(null, "10.0.0.1");
        realNodes.add("10.0.0.2");
        addVirtualNode.invoke(null, "10.0.0.2");
        realNodes.add("10.0.0.3");
        addVirtualNode.invoke(null, "10.0.0.3");
        if (virtualNodes.size() != 30) throw new AssertionError("expected 30 vnodes, got " + virtualNodes.size());
        long count = virtualNodes.values().stream().filter(v -> v.startsWith("10.0.0.1##VN")).count();
        if (count != 10) throw new AssertionError("expected 10 vnodes for 10.0.0.1, got " + count);
        System.out.println("addVirtualNode OK (30 vnodes for 3 servers)");

        // 4. getServer routes to the server owning the first vnode clockwise
        for (String key : new String[]{"1.2.3.4", "8.8.8.8", "client-A", "key-123"}) {
            int h = (int) getHash.invoke(null, key);
            SortedMap<Integer, String> tail = virtualNodes.tailMap(h);
            String server;
            if (tail.isEmpty()) {
                continue; // wrap-around case: original code NPEs here, skip
            }
            server = tail.get(tail.firstKey());
            server = server.substring(0, server.indexOf("##"));
            String got = (String) getServer.invoke(null, key);
            if (!got.equals(server)) throw new AssertionError("getServer mismatch for " + key + ": " + got + " != " + server);
            if (!realNodes.contains(got)) throw new AssertionError("getServer returned non-real server: " + got);
        }
        System.out.println("getServer OK (routes to first clockwise vnode owner)");

        // 5. deleteServer removes server + its 10 vnodes, other servers untouched
        deleteServer.invoke(null, "10.0.0.2");
        if (realNodes.contains("10.0.0.2")) throw new AssertionError("real node not removed");
        if (virtualNodes.size() != 20) throw new AssertionError("expected 20 vnodes after delete, got " + virtualNodes.size());
        for (String v : virtualNodes.values()) {
            if (v.startsWith("10.0.0.2##VN")) throw new AssertionError("vnode of deleted server remains: " + v);
        }
        System.out.println("deleteServer OK");

        // 6. consistent hashing property: adding a server remaps only a fraction of keys
        Map<String, String> before = new HashMap<>();
        List<String> keys = new ArrayList<>();
        for (int i = 0; i < 500; i++) {
            String k = "client-" + i;
            keys.add(k);
            int h = (int) getHash.invoke(null, k);
            SortedMap<Integer, String> tail = virtualNodes.tailMap(h);
            if (!tail.isEmpty()) before.put(k, (String) getServer.invoke(null, k));
        }
        realNodes.add("10.0.0.4");
        addVirtualNode.invoke(null, "10.0.0.4");
        int remapped = 0;
        for (Map.Entry<String, String> e : before.entrySet()) {
            String now = (String) getServer.invoke(null, e.getKey());
            if (!now.equals(e.getValue())) remapped++;
        }
        double frac = (double) remapped / before.size();
        System.out.println("remap fraction after adding 4th server: " + remapped + "/" + before.size() + " = " + frac);
        if (frac > 0.7) throw new AssertionError("too many keys remapped, not consistent hashing");
        System.out.println("ALL TESTS PASSED");
    }
}
